using System.Globalization;
using System.Xml.Linq;

namespace AoMDivineDataEditor.Classes;

/// <summary>Ownership of the two string fields generated by the Ability editor.</summary>
internal static class AbilityStringPolicy
{
    internal static readonly string[] FieldTags = ["displaynameid", "rolloverid"];

    internal static string BuildId(string name, bool rollover)
    {
        var token = new string(name.Trim().ToUpperInvariant()
            .Select(character => char.IsLetterOrDigit(character) ? character : '_').ToArray());
        while (token.Contains("__", StringComparison.Ordinal)) token = token.Replace("__", "_", StringComparison.Ordinal);
        return $"STR_ABILITY_{token.Trim('_')}{(rollover ? "_LR" : "")}";
    }

    internal static IReadOnlySet<string> CollectOwnedStringIds(XElement power)
        => Mappings(power, (string?)power.Attribute("name") ?? "").Keys.ToHashSet(StringComparer.OrdinalIgnoreCase);

    internal static IReadOnlyList<OwnedStringRename> RenameOwnedStringIds(XElement before,
        XElement candidate, string newName, IReadOnlySet<string> available)
    {
        var mappings = Mappings(before, newName);
        var changes = new List<OwnedStringRename>();
        foreach (var field in Fields(candidate))
        {
            var id = field.Value.Trim();
            if (!available.Contains(id) || !mappings.TryGetValue(id, out var next) ||
                id.Equals(next, StringComparison.OrdinalIgnoreCase)) continue;
            XmlTriviaPreserver.SetText(field, next);
            changes.Add(new(field.Name.LocalName, id, next));
        }
        return changes;
    }

    private static Dictionary<string, string> Mappings(XElement power, string newName)
    {
        var mappings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var name = (string?)power.Attribute("name") ?? "";
        if (power.Name != "power" || name.Length == 0) return mappings;
        foreach (var field in Fields(power))
        {
            var rollover = field.Name.LocalName.Equals("rolloverid", StringComparison.OrdinalIgnoreCase);
            var id = field.Value.Trim();
            var basis = BuildId(name, rollover);
            var stem = rollover ? basis[..^3] : basis;
            var body = rollover && id.EndsWith("_LR", StringComparison.OrdinalIgnoreCase) ? id[..^3] : id;
            if (rollover && !id.EndsWith("_LR", StringComparison.OrdinalIgnoreCase)) continue;
            if (!body.StartsWith(stem, StringComparison.OrdinalIgnoreCase)) continue;
            var suffix = body[stem.Length..];
            // Allocation is BASE, BASE_2, BASE_3 ...; rollover appends _LR after the number.
            if (suffix.Length != 0 && !(suffix.StartsWith('_') &&
                    int.TryParse(suffix.AsSpan(1), NumberStyles.None, CultureInfo.InvariantCulture, out var index) &&
                    index >= 2 && suffix == "_" + index.ToString(CultureInfo.InvariantCulture))) continue;
            var next = BuildId(newName, false) + suffix + (rollover ? "_LR" : "");
            if (mappings.TryGetValue(id, out var previous) && !previous.Equals(next, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException($"Ability string '{id}' has ambiguous ownership. No files were written.");
            mappings[id] = next;
        }
        return mappings;
    }

    internal static IEnumerable<XElement> Fields(XElement power) => power.Elements().Where(field =>
        field.Name.Namespace == XNamespace.None && !field.HasElements &&
        FieldTags.Contains(field.Name.LocalName, StringComparer.OrdinalIgnoreCase));
}
